CREATE DATABASE IF NOT EXISTS paysafe CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE paysafe;
CREATE TABLE regions (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE branches (id VARCHAR(36) PRIMARY KEY, region_id VARCHAR(36) NOT NULL, name VARCHAR(120) NOT NULL, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_branch_region FOREIGN KEY(region_id) REFERENCES regions(id), INDEX idx_branch_region(region_id));
CREATE TABLE users (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('HQ_ADMIN','REGIONAL_MANAGER','BRANCH_MANAGER','BRANCH_STAFF','CUSTOMER') NOT NULL, status ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE staff_profiles (user_id CHAR(36) PRIMARY KEY, region_id VARCHAR(36), branch_id VARCHAR(36), full_name VARCHAR(160) NOT NULL, phone VARCHAR(32), CONSTRAINT fk_staff_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_staff_region FOREIGN KEY(region_id) REFERENCES regions(id), CONSTRAINT fk_staff_branch FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE customers (id CHAR(36) PRIMARY KEY, user_id CHAR(36) UNIQUE, branch_id VARCHAR(36) NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, phone VARCHAR(32), status ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(branch_id) REFERENCES branches(id), INDEX idx_customer_branch(branch_id));
CREATE TABLE accounts (id VARCHAR(32) PRIMARY KEY, customer_id CHAR(36) NOT NULL, branch_id VARCHAR(36) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'INR', balance DECIMAL(19,2) NOT NULL DEFAULT 0.00, status ENUM('ACTIVE','FROZEN','CLOSED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(branch_id) REFERENCES branches(id), INDEX idx_account_customer(customer_id), CHECK(balance >= 0));
CREATE TABLE transactions (id CHAR(36) PRIMARY KEY, type ENUM('TRANSFER','DEPOSIT','WITHDRAWAL','REVERSAL') NOT NULL, source_account_id VARCHAR(32), destination_account_id VARCHAR(32), amount DECIMAL(19,2) NOT NULL, status ENUM('CREATED','VALIDATING','SIMULATING','COMPLETED','FAILED','REJECTED','REVERSED') NOT NULL, initiator_user_id CHAR(36), reference_text VARCHAR(120), idempotency_key VARCHAR(128) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, FOREIGN KEY(source_account_id) REFERENCES accounts(id), FOREIGN KEY(destination_account_id) REFERENCES accounts(id), FOREIGN KEY(initiator_user_id) REFERENCES users(id), CHECK(amount > 0), INDEX idx_tx_created(created_at), INDEX idx_tx_status(status));
CREATE TABLE ledger_entries (id CHAR(36) PRIMARY KEY, transaction_id CHAR(36) NOT NULL, account_id VARCHAR(32) NOT NULL, entry_type ENUM('DEBIT','CREDIT') NOT NULL, amount DECIMAL(19,2) NOT NULL, reference_text VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(transaction_id) REFERENCES transactions(id), FOREIGN KEY(account_id) REFERENCES accounts(id), CHECK(amount > 0), INDEX idx_ledger_account(account_id,created_at));
CREATE TABLE network_nodes (id VARCHAR(64) PRIMARY KEY, name VARCHAR(120) NOT NULL, node_type ENUM('CUSTOMER','BRANCH','REGION','HQ') NOT NULL, branch_id VARCHAR(36), status ENUM('ONLINE','OFFLINE') NOT NULL DEFAULT 'ONLINE', metadata JSON, FOREIGN KEY(branch_id) REFERENCES branches(id));
CREATE TABLE network_links (id VARCHAR(64) PRIMARY KEY, source_node_id VARCHAR(64) NOT NULL, destination_node_id VARCHAR(64) NOT NULL, latency_ms INT NOT NULL, bandwidth_mbps DECIMAL(10,2) NOT NULL, packet_loss DECIMAL(5,4) NOT NULL DEFAULT 0, status ENUM('ONLINE','OFFLINE') NOT NULL DEFAULT 'ONLINE', FOREIGN KEY(source_node_id) REFERENCES network_nodes(id), FOREIGN KEY(destination_node_id) REFERENCES network_nodes(id), CHECK(latency_ms BETWEEN 1 AND 2000), CHECK(bandwidth_mbps > 0), CHECK(packet_loss BETWEEN 0 AND 1), INDEX idx_link_source(source_node_id));
CREATE TABLE simulation_runs (id VARCHAR(64) PRIMARY KEY, transaction_id CHAR(36), source_node_id VARCHAR(64) NOT NULL, destination_node_id VARCHAR(64) NOT NULL, route_json JSON, seed_value BIGINT, status ENUM('RUNNING','COMPLETED','FAILED','PAUSED') NOT NULL, latency_ms INT, packets_sent INT NOT NULL DEFAULT 0, packets_delivered INT NOT NULL DEFAULT 0, packets_lost INT NOT NULL DEFAULT 0, retries INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, FOREIGN KEY(transaction_id) REFERENCES transactions(id), FOREIGN KEY(source_node_id) REFERENCES network_nodes(id), FOREIGN KEY(destination_node_id) REFERENCES network_nodes(id));
CREATE TABLE packet_events (id CHAR(36) PRIMARY KEY, simulation_id VARCHAR(64) NOT NULL, sequence_no INT NOT NULL, event_type VARCHAR(48) NOT NULL, source_node_id VARCHAR(64), destination_node_id VARCHAR(64), attempt_no INT NOT NULL DEFAULT 1, latency_ms INT, event_payload JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(simulation_id) REFERENCES simulation_runs(id), UNIQUE KEY uq_sim_sequence(simulation_id,sequence_no), INDEX idx_packet_event_time(simulation_id,created_at));
CREATE TABLE audit_logs (id CHAR(36) PRIMARY KEY, actor_user_id CHAR(36), actor_role VARCHAR(32) NOT NULL, action_name VARCHAR(100) NOT NULL, resource_type VARCHAR(80), resource_id VARCHAR(100), outcome VARCHAR(32) NOT NULL, correlation_id VARCHAR(100), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX idx_audit_created(created_at));
CREATE TABLE security_events (id CHAR(36) PRIMARY KEY, actor_user_id CHAR(36), event_type VARCHAR(100) NOT NULL, outcome VARCHAR(32) NOT NULL, details JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id));
CREATE TABLE user_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, session_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_session_expiry(expires_at));
CREATE TABLE idempotency_records (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, request_hash CHAR(64) NOT NULL, response_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_idempotency(user_id,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id));
